# Generated by Cursor (plan: website [xxxDOTyyy] -> xxx dot yyy)
"""Scan for [xxxDOTyyy] or [xxxDOTyyy,] and replace DOT with ' dot '."""

import re

# Case-insensitive DOT inside brackets
WEBSITE_DOT_RE = re.compile(r"\[([^\]]*?)DOT([^\]]*)\]", re.IGNORECASE)


def scan_turn_website_dot(
    text: str,
    path_str: str = "",
) -> list[tuple[str, int, str, str]]:
    """Emit (website_dot, start_index, full_span, path_str) for each [xxxDOTyyy] match."""
    result: list[tuple[str, int, str, str]] = []
    for m in WEBSITE_DOT_RE.finditer(text):
        result.append(("website_dot", m.start(), m.group(0), path_str))
    return result
